public class ClockEntry
{
    public int EmployeeId { get; }
    public DateTime ClockIn { get; }
    public DateTime? ClockOut { get; private set; }

    public ClockEntry(int employeeId, DateTime clockIn)
    {
        EmployeeId = employeeId;
        ClockIn = clockIn;
        // ClockOut is left null on purpose -- that is what "open" means.
    }
}

public Employee(int employeeId, string name, Address address)
{
    EmployeeId = employeeId;
    Name = name;
    Address = address;
}

// Services/ClockEntryService.cs -- the real ClockIn implementation
public void ClockIn(int employeeId)
{
    var entry = new ClockEntry(employeeId, DateTime.Now);
    _clockEntryRepository.SaveClockEntry(entry);
}
